package dev.bre.decision.log;

import dev.bre.decision.api.DecisionApi.DecisionResponse;
import java.time.Instant;
import java.util.Objects;

/**
 * A durable decision record (LLD §5.3).
 *
 * <p>Holds the resolved {@code asOf} and the facts the decision was made from, which is what makes
 * "replay this decision from March" exact (D7): the explanation is regenerated by re-evaluating the
 * stored facts rather than by storing a trace per rule, which is roughly ten times less storage for
 * the same answer.
 *
 * @param decisionId the identifier
 * @param tenantId the tenant
 * @param requestId the caller's idempotency key
 * @param recordedAt when the record was written. A timestamp on the record, not an input to
 *     evaluation — the engine itself never reads a clock (D8).
 * @param response the decision as returned to the caller
 * @param factsJson the fact snapshot, as submitted
 */
public record DecisionRecord(
    String decisionId,
    String tenantId,
    String requestId,
    Instant recordedAt,
    DecisionResponse response,
    String factsJson) {

  /** Creates a record. */
  public DecisionRecord {
    Objects.requireNonNull(decisionId, "decisionId");
    Objects.requireNonNull(tenantId, "tenantId");
    Objects.requireNonNull(requestId, "requestId");
  }
}
